import{_ as t,o as e,c as o,ae as a}from"./chunks/framework.Dn7Y7LSn.js";const g=JSON.parse('{"title":"Laravel Directory Structure","description":"","frontmatter":{},"headers":[],"relativePath":"laravel/directory-structure.md","filePath":"laravel/directory-structure.md"}'),s={name:"laravel/directory-structure.md"};function l(i,r,n,c,u,d){return e(),o("div",null,[...r[0]||(r[0]=[a('<h1 id="laravel-directory-structure" tabindex="-1">Laravel Directory Structure <a class="header-anchor" href="#laravel-directory-structure" aria-label="Permalink to &quot;Laravel Directory Structure&quot;">​</a></h1><p>লারাভেল প্রজেক্টের ফোল্ডার স্ট্রাকচার বেশ বড় মনে হতে পারে, তবে এটি অত্যন্ত সুশৃঙ্খল। নিচে গুরুত্বপূর্ণ ফোল্ডারগুলোর কাজ দেওয়া হলো:</p><ul><li><strong>app/</strong>: এখানে আপনার প্রজেক্টের মূল লজিক থাকে (Models, Controllers, Providers)।</li><li><strong>bootstrap/</strong>: ফ্রেমওয়ার্ক বুটস্ট্র্যাপ করার ফাইলগুলো এখানে থাকে।</li><li><strong>config/</strong>: প্রজেক্টের সব কনফিগারেশন ফাইল এখানে থাকে।</li><li><strong>database/</strong>: ডাটাবেজ মাইগ্রেশন, সিডার এবং ফ্যাক্টরি এখানে থাকে।</li><li><strong>public/</strong>: এটি প্রজেক্টের এন্ট্রি পয়েন্ট (index.php) এবং এখানে CSS, JS, Images রাখা হয়।</li><li><strong>resources/</strong>: এখানে আপনার View (Blade files), ল্যাঙ্গুয়েজ এবং আন-কম্পাইলড রিসোর্স থাকে।</li><li><strong>routes/</strong>: সব ধরণের রাউটিং এখানে ডিফাইন করা হয় (web.php, api.php)।</li><li><strong>storage/</strong>: লগ ফাইল এবং ইউজারের আপলোড করা ফাইল এখানে জমা হয়।</li><li><strong>vendor/</strong>: আপনার ইউজ করা সব প্যাকেজ বা লাইব্রেরি এখানে থাকে (Composer-এর মাধ্যমে)।</li><li><strong>.env</strong>: এখানে ডাটাবেজ এবং অন্যান্য এনভায়রনমেন্ট কনফিগারেশন রাখা হয়।</li></ul>',3)])])}const _=t(s,[["render",l]]);export{g as __pageData,_ as default};
